SELECT TO_DATE(sessions.started_at) started_day, DATE_TRUNC('MONTH', sessions.started_at) started_month, MAX(web_events.event_time) last_event_time, AVG(web_events.duration_sec) avg_duration_sec FROM web_events JOIN sessions ON web_events.session_id = sessions.id WHERE sessions.country = 'TH' GROUP BY TO_DATE(sessions.started_at), DATE_TRUNC('MONTH', sessions.started_at) ORDER BY started_month, started_day
